var test=require("tape"),load=require("./"),expectedArial=require("./fnt/Arial.json"),fs=require("fs"),http=require("http"),arialBin=fs.readFileSync("fnt/Arial.bin");test("should load from server URL",function(e){e.plan(1);const r=http.createServer((e,r)=>{r.end(arialBin)});r.listen(8003,()=>{load({url:"http://localhost:8003",binary:!0},(t,a)=>{t?e.fail(t):e.deepEqual(a,expectedArial),r.close()})})});